  function predictLiveTripSoc(level, run, opts) {
    const vehicle = getVehicleById(run.plan.vehicleId);
    const legs = getActiveRouteLegs(level, run.plan);
    let soc = opts?.overrideSocPct !== void 0 ? opts.overrideSocPct : run.socPct;
    const startLeg = Math.min(legs.length - 1, Math.max(0, run.currentLegIndex));
    let distAccum = 0;
    let liveCons100 = vehicle.baseConsumption100;
    let nextTarget = null;
    for (let i = startLeg; i < legs.length; i++) {
      const spec = legs[i];
      const edge = getEdgeById(spec.edgeId);
      const lp = run.plan.legPlans.find((x) => x.legIndex === i);
      const weather = i === startLeg ? run.activeWeather || spec.weatherOverride || edge.defaultWeather : spec.weatherOverride || edge.defaultWeather;
      const preset = lp?.targetSpeedKmh || defaultLegSpeedKmh(edge, vehicle.maxSpeedKmh, weather);
      const chosenSpeed = Math.min(
        vehicle.maxSpeedKmh,
        i === startLeg && opts?.overrideSpeedKmh !== void 0 ? opts.overrideSpeedKmh : i === startLeg ? run.currentSpeedKmh || preset : preset
      );
      const capped = drivenSpeedKmh(edge, weather, chosenSpeed);
      const speed = i === startLeg && run.currentSpeedKmh > 0 ? Math.min(capped, run.currentSpeedKmh) : congestedCruiseKmh(capped, edge.baseTrafficRisk);
      const elevGain = spec.reverse ? edge.elevationLossM : edge.elevationGainM;
      const elevLoss = spec.reverse ? edge.elevationGainM : edge.elevationLossM;
      const cons100 = computeConsumptionKwh100(
        vehicle,
        speed,
        weather,
        elevGain,
        elevLoss,
        edge.distanceKm,
        level.trailerWeightKg || 0,
        !!run.plan.behindTruckMode
      );
      if (i === startLeg) {
        liveCons100 = cons100;
      }
      const startProgress01 = i === startLeg ? Math.min(1, Math.max(0, run.legProgressKm / Math.max(1, edge.distanceKm))) : 0;
      const stopsOnLeg = run.plan.plannedStops.filter(
        (s) => s.legIndex === i && !run.completedStopIds.includes(s.chargerId) && !run.skippedStopIds.includes(s.chargerId) && s.chargerId !== opts?.skipStationId
      ).map((s) => {
        const st = getChargersForEdge(edge.id).find((c) => c.id === s.chargerId);
        if (!st) return null;
        const p = spec.reverse ? 1 - st.edgeProgress : st.edgeProgress;
        return { stop: s, station: st, progress: p };
      }).filter((x) => x !== null && x.progress > startProgress01 + 2e-3).sort((a, b) => a.progress - b.progress);
      let cursor = startProgress01;
      for (const item of stopsOnLeg) {
        const segKm = Math.max(0, (item.progress - cursor) * edge.distanceKm);
        const segKwh = segKm / 100 * cons100;
        soc -= segKwh / vehicle.batteryKwh * 100;
        distAccum += segKm;
        if (!nextTarget) {
          nextTarget = {
            name: item.station.name,
            kind: "charger",
            distKm: Math.max(1, Math.round(distAccum)),
            socPct: Math.round(soc)
          };
        }
        soc = Math.min(100, Math.max(soc, item.stop.targetSocPct));
        cursor = item.progress;
      }
      const remKm = Math.max(0, (1 - cursor) * edge.distanceKm);
      const remKwh = remKm / 100 * cons100;
      soc -= remKwh / vehicle.batteryKwh * 100;
      distAccum += remKm;
      if (!nextTarget && (spec.citySegmentAtEnd === "hannover_messe" || spec.destinationAtEnd || spec.overnightAtEnd)) {
        const toCity = getCityById(spec.reverse ? edge.fromCityId : edge.toCityId);
        nextTarget = {
          name: toCity.name,
          kind: "turnaround",
          distKm: Math.max(1, Math.round(distAccum)),
          socPct: Math.round(soc)
        };
      }
    }
    const finalCity = getCityById(level.destinationCityId);
    if (!nextTarget) {
      nextTarget = {
        name: `Ziel ${finalCity.name}`,
        kind: "destination",
        distKm: Math.max(1, Math.round(distAccum)),
        socPct: Math.round(soc)
      };
    }
    const finalSoc = Math.round(soc);
    return {
      nextStopName: nextTarget.name,
      nextStopKind: nextTarget.kind,
      distanceToNextKm: nextTarget.distKm,
      predictedArrivalNextSocPct: nextTarget.socPct,
      predictedFinalSocPct: finalSoc,
      isCriticalNext: nextTarget.socPct <= 5,
      isCriticalFinal: finalSoc <= 5,
      consumptionKwh100: liveCons100
    };
  }
  function findNearestAvailableCharger(level, plan, legIndex, progress01, alreadyVisitedIds) {
    const legs = getActiveRouteLegs(level, plan);
    for (let i = legIndex; i < legs.length; i++) {
      const spec = legs[i];
      const candidates = getChargersForEdge(spec.edgeId).filter((c) => !alreadyVisitedIds.includes(c.id)).map((c) => {
        const p = spec.reverse ? 1 - c.edgeProgress : c.edgeProgress;
        return { station: c, p };
      }).filter((x) => i > legIndex ? true : x.p > progress01 + 0.03).sort((a, b) => a.p - b.p);
      if (candidates.length > 0) {
        return { legIndex: i, station: candidates[0].station };
      }
    }
    return null;
  }

  // src/sim/ScoringEngine.ts
  function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
  }
  function evaluateRun(level, run, cleanParkBonus) {
    const w = level.scoringWeights;
    const vehicle = getVehicleById(run.plan.vehicleId);
    const timeDelta = run.elapsedMinutes - level.targetArrivalMinutes;
    const timeScore = clamp(
      timeDelta <= 0 ? 100 - Math.max(0, -timeDelta * 0.05) : 100 - timeDelta * 1.15,
      12,
      100
    );
    const totalCostEur = Number(
      (run.chargingCostEur + run.subscriptionCostEur + run.tollsAndFinesEur + (run.lodgingCostEur || 0)).toFixed(2)
    );
    const benchmarkCost = Math.max(30, run.distanceDrivenKm * (level.costBenchmarkEurPerKm ?? 0.082));
    const costRatio = totalCostEur / benchmarkCost;
    const costScore = clamp(115 - costRatio * 34, 15, 100);
    const stressPenalty = run.peakStress * 0.65 + run.stress * 0.35;
    const stressScore = w.stress === 0 ? 100 : clamp(108 - stressPenalty * 1.05, 10, 100);
    const avgConsumption = run.energyUsedKwh / Math.max(1, run.distanceDrivenKm) * 100;
    const efficiencyRatio = avgConsumption / vehicle.baseConsumption100;
    const effBase = clamp(128 - efficiencyRatio * 34 + run.chargingEfficiencyBonus, 15, 100);
    const collisionPenalty = run.collisionsCount * 14;
    const parkBonus = cleanParkBonus ? 12 : 0;
    const decisionsScore = clamp(
      56 + run.decisionScoreAccum + run.goodReplanCount * 8 + parkBonus - collisionPenalty,
      10,
      100
    );
    const weighted = timeScore * w.time + costScore * w.cost + stressScore * w.stress + effBase * w.efficiency + decisionsScore * w.decisions;
    const totalScore = Math.round(clamp(weighted * 10, 100, 1e3));
    const prizeMultiplier = 0.55 + totalScore / 1e3 * 0.95;
    const prizeMoneyEur = Math.round(level.rewardBaseEur * prizeMultiplier);
    let gradeLabel = "Solide E-Fahrt";
    if (totalScore >= 880) gradeLabel = "S-Rang \xB7 Langstrecken-Meister!";
    else if (totalScore >= 760) gradeLabel = "A-Rang \xB7 Souver\xE4n geplant";
    else if (totalScore >= 620) gradeLabel = "B-Rang \xB7 Sicher angekommen";
    else if (totalScore < 480) gradeLabel = "C-Rang \xB7 Nervenaufreibend";
    return {
      totalScore,
      subScores: {
        time: Math.round(timeScore),
        cost: Math.round(costScore),
        stress: Math.round(stressScore),
        efficiency: Math.round(effBase),
        decisions: Math.round(decisionsScore)
      },
      weights: { ...w },
      totalMinutes: Math.round(run.elapsedMinutes),
      targetMinutes: level.targetArrivalMinutes,
      totalCostEur,
      avgConsumptionKwh100: Number(avgConsumption.toFixed(1)),
      peakStress: Math.round(run.peakStress),
      prizeMoneyEur,
      cleanArrival: cleanParkBonus && run.collisionsCount === 0,
      gradeLabel
    };
  }

