        const flickerDip = nv.flicker && Math.sin(t * 17 + nv.phase) > 0.92 && Math.sin(t * 5.3 + nv.phase) > 0.3 ? 0.45 : 1;
        const pulse = (0.88 + Math.sin(t * 2.6 + nv.phase) * 0.12) * flickerDip;
        nv.halo.setAlpha(0.46 * neonBoost * pulse);
