        y: this.player.y,
        rotation: this.player.rotation,
        speed: this.carSpeed,
        onGrass: isGrassSurface(this.player.x, this.player.y, this.place.grass, this.place.asphalt, this.place.buildings),
        wetRoad: this.roadWet,
        dt
