        const doneLabel = this.preset === "koeln_ring" ? "\u{1F6E3}\uFE0F Weiter auf die A1" : this.preset === "ferry_denmark" ? "\u26F4\uFE0F F\xE4hre erreicht" : "\u{1F6E3}\uFE0F Auffahrt A4 \u2013 Gute Fahrt!";
